export const IS_BROWSER = typeof document !== 'undefined'

function overlaps(a, b) {
  if (a === b) return false
  if (a.x + a.w <= b.x) return false
  if (a.x >= b.x + b.w) return false
  if (a.y + a.h <= b.y) return false
  if (a.y >= b.y + b.h) return false
  return true
}

function firstOverlap(tiles, tile) {
  return tiles.find((t) => overlaps(t, tile))
}

function allOverlaps(tiles, tile) {
  return tiles.filter((t) => overlaps(t, tile))
}

function frozenOnly(tiles) {
  return tiles.filter((t) => t.frozen)
}

function sortByRowThenColumn(tiles, priorityId) {
  return [].concat(tiles).sort((a, b) => {
    if (a.y === b.y) {
      if (priorityId !== undefined) {
        if (a.id === priorityId) return -1
        if (b.id === priorityId) return 1
      }
      if (a.x === b.x) return 0
    }
    if (a.y > b.y || (a.y === b.y && a.x > b.x)) return 1
    return -1
  })
}

function sharesColumns(a, b) {
  return !(a.x + a.w <= b.x) && !(a.x >= b.x + b.w)
}

function fall(settled, tile, gravity) {
  const column = settled.filter((t) => sharesColumns(t, tile))

  if (gravity) {
    while (tile.y > 0 && !firstOverlap(column, tile)) {
      tile.y--
    }
  }

  let hit
  while ((hit = firstOverlap(column, tile))) {
    tile.y = hit.y + hit.h
  }
}

function pushAside(tiles, blocker, tile, isUserAction) {
  if (isUserAction) {
    const probe = {
      x: tile.x,
      y: Math.max(blocker.y - tile.h, 0),
      w: tile.w,
      h: tile.h,
      id: '-1'
    }
    if (!firstOverlap(tiles, probe)) {
      return moveTile(tiles, tile, undefined, probe.y, false)
    }
  }

  return moveTile(tiles, tile, undefined, tile.y + 1, false)
}

function slideAlongRow(tiles, tile, x) {
  const dir = x > tile.x ? 1 : -1
  const row = tiles.filter((t) => t !== tile && !t.frozen && t.y === tile.y)
  const placed = new Map()
  let at = tile.x

  for (let step = tile.x + dir; dir > 0 ? step <= x : step >= x; step += dir) {
    const probe = { x: dir > 0 ? Math.max(at, step) : Math.min(at, step), w: tile.w }
    const ahead = row
      .filter((t) => !placed.has(t) && sharesColumns(t, probe))
      .sort((a, b) => dir * (a.x - b.x))

    if (!ahead.length) {
      at = probe.x
      continue
    }

    const crossed = []
    for (const t of ahead) {
      const middle = t.x + t.w / 2
      if (dir > 0 ? probe.x + tile.w > middle : probe.x < middle) crossed.push(t)
      else break
    }
    if (!crossed.length) continue

    let edge = dir > 0 ? at : at + tile.w
    for (const t of crossed) {
      if (dir > 0) {
        placed.set(t, edge)
        edge += t.w
      } else {
        edge -= t.w
        placed.set(t, edge)
      }
    }
    at = dir > 0 ? edge : edge - tile.w
  }

  return { at, placed }
}

function isNum(n) {
  return typeof n === 'number' && !Number.isNaN(n)
}

export function getLastRow(tiles) {
  let max = 0
  for (let i = 0, len = tiles.length; i < len; i++) {
    const edge = tiles[i].y + tiles[i].h
    if (edge > max) max = edge
  }
  return max
}

export function copyTiles(tiles) {
  return (tiles || []).map((tile) => ({ ...tile }))
}

export function getTileById(tiles, id) {
  return tiles.find((tile) => tile.id === id)
}

export function applyGravity(tiles, gravity, priorityId) {
  const settled = frozenOnly(tiles)
  const sorted = sortByRowThenColumn(tiles, priorityId)

  for (let i = 0, len = sorted.length; i < len; i++) {
    const tile = sorted[i]

    if (!tile.frozen) {
      fall(settled, tile, gravity)
      settled.push(tile)
    }

    delete tile.moved
  }
}

export function moveTile(tiles, tile, x, y, isUserAction, preventOverlap) {
  if (tile.frozen) return tiles

  const oldX = tile.x
  const oldY = tile.y

  if (
    isUserAction &&
    !preventOverlap &&
    typeof x === 'number' &&
    x !== oldX &&
    (y === undefined || y === oldY) &&
    tiles.includes(tile)
  ) {
    const { at, placed } = slideAlongRow(tiles, tile, x)
    x = at
    tile.x = at
    tile.moved = true
    for (const [t, px] of placed) moveTile(tiles, t, px, t.y, false)
  }

  const movingUp = y && tile.y > y
  if (typeof x === 'number') tile.x = x
  if (typeof y === 'number') tile.y = y
  tile.moved = true

  let sorted = sortByRowThenColumn(tiles)
  if (movingUp) sorted = sorted.reverse()
  const hits = allOverlaps(sorted, tile)

  if (preventOverlap && hits.length) {
    tile.x = oldX
    tile.y = oldY
    tile.moved = false
    return tiles
  }

  for (let i = 0, len = hits.length; i < len; i++) {
    const hit = hits[i]

    if (hit.moved) continue
    if (tile.y > hit.y && tile.y - hit.y > hit.h / 4) continue

    if (hit.frozen) {
      tiles = pushAside(tiles, hit, tile, isUserAction)
    } else {
      tiles = pushAside(tiles, tile, hit, isUserAction)
    }
  }

  return tiles
}

export function findKeyboardSlot(tiles, id, dx, dy, columns, gravity) {
  const tile = getTileById(tiles, id)
  if (!tile) return null

  const lastRow = getLastRow(tiles)
  let x = tile.x
  let y = tile.y

  for (;;) {
    const nextX = Math.max(0, Math.min(columns - tile.w, x + dx))
    const nextY = Math.max(0, Math.min(lastRow, y + dy))
    if (nextX === x && nextY === y) return null
    x = nextX
    y = nextY

    const trial = copyTiles(tiles)
    moveTile(trial, getTileById(trial, id), x, y, true, false)
    applyGravity(trial, gravity, id)
    if (trial.some((t, i) => t.x !== tiles[i].x || t.y !== tiles[i].y)) return { x, y }
  }
}

export function validateTiles(tiles, context = 'tiles') {
  if (!Array.isArray(tiles)) throw new Error(`vue3-grid-board: ${context} must be an array.`)

  const seen = new Set()

  tiles.forEach((tile, i) => {
    for (const key of ['x', 'y', 'w', 'h']) {
      if (typeof tile[key] !== 'number') {
        throw new Error(`vue3-grid-board: ${context}[${i}].${key} must be a number.`)
      }
    }
    if (tile.id === undefined || tile.id === null) {
      throw new Error(`vue3-grid-board: ${context}[${i}].id is required.`)
    }
    if (typeof tile.id !== 'number' && typeof tile.id !== 'string') {
      throw new Error(`vue3-grid-board: ${context}[${i}].id must be a string or a number.`)
    }
    if (seen.has(tile.id)) {
      throw new Error(
        `vue3-grid-board: ${context}[${i}].id must be unique (saw "${tile.id}" twice).`
      )
    }
    seen.add(tile.id)
    if (tile.frozen !== undefined && typeof tile.frozen !== 'boolean') {
      throw new Error(`vue3-grid-board: ${context}[${i}].frozen must be a boolean.`)
    }
  })
}

export function getPointerOffset(e) {
  const offsetParent = e.target.offsetParent || document.body
  const rect = offsetParent.getBoundingClientRect()

  return {
    x: e.clientX + offsetParent.scrollLeft - rect.left,
    y: e.clientY + offsetParent.scrollTop - rect.top
  }
}

export function getFrameDelta(lastX, lastY, x, y) {
  if (!isNum(lastX)) {
    return { deltaX: 0, deltaY: 0, lastX: x, lastY: y, x, y }
  }
  return { deltaX: x - lastX, deltaY: y - lastY, lastX, lastY, x, y }
}
